changeSet.sql:
ALTER TABLE public.review ADD CONSTRAINT ck_review_version_kind CHECK (version_kind IN ('REPOSITORY_COMMIT', 'SUBMITTED_VERSION', 'ITEM_REVISION')) NOT VALID;
ALTER TABLE public.review ADD CONSTRAINT ck_review_audience CHECK (audience IN ('OPERATIONAL', 'TEAM', 'PERSONAL')) NOT VALID;
ALTER TABLE public.review ADD CONSTRAINT ck_review_audience_team CHECK ((audience_team_id IS NULL) = (audience IS DISTINCT FROM 'TEAM')) NOT VALID;
ALTER TABLE public.review ADD CONSTRAINT ck_review_audience_version_kind CHECK ((audience IS NULL) = (version_kind IS NULL)) NOT VALID;
ALTER TABLE public.review ADD CONSTRAINT ck_review_version_kind_scan CHECK (version_kind IS NULL OR (kind = 'SCAN') = (version_kind = 'REPOSITORY_COMMIT')) NOT VALID;
ALTER TABLE public.review ADD CONSTRAINT sfk_review_setup FOREIGN KEY (setup_id, workspace_id) REFERENCES public.review_setup (id, workspace_id) ON DELETE SET NULL (setup_id) NOT VALID;

