changeSet.createProcedure:
CREATE FUNCTION public.admit_review_audience_team() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM public.project_team t
        WHERE t.id = NEW.audience_team_id AND t.workspace_id = NEW.workspace_id AND t.removed_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a team review names a standing team project of its workspace' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$

CREATE FUNCTION public.refuse_review_audience_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (OLD.audience IS NOT NULL
            AND (NEW.audience IS DISTINCT FROM OLD.audience OR NEW.audience_team_id IS DISTINCT FROM OLD.audience_team_id))
        OR (OLD.version_kind IS NOT NULL AND NEW.version_kind IS DISTINCT FROM OLD.version_kind)
        OR (NEW.setup_id IS NOT NULL AND NEW.setup_id IS DISTINCT FROM OLD.setup_id) THEN
        RAISE EXCEPTION 'a review keeps the audience, the kind of version and the setup it was created with' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END $$

changeSet.sql:
CREATE TRIGGER review_audience_team_admit BEFORE INSERT ON public.review
    FOR EACH ROW WHEN (NEW.audience_team_id IS NOT NULL) EXECUTE FUNCTION public.admit_review_audience_team();
CREATE TRIGGER review_audience_team_still_admitted AFTER UPDATE OF audience_team_id, workspace_id ON public.review
    FOR EACH ROW WHEN (NEW.audience_team_id IS NOT NULL
        AND (NEW.audience_team_id IS DISTINCT FROM OLD.audience_team_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id))
    EXECUTE FUNCTION public.admit_review_audience_team();
CREATE TRIGGER review_audience_fixed AFTER UPDATE OF audience, audience_team_id, version_kind, setup_id ON public.review
    FOR EACH ROW EXECUTE FUNCTION public.refuse_review_audience_change();

changeSet.rollback:
DROP TRIGGER review_audience_fixed ON public.review;
DROP TRIGGER review_audience_team_still_admitted ON public.review;
DROP TRIGGER review_audience_team_admit ON public.review;
DROP FUNCTION public.refuse_review_audience_change();
DROP FUNCTION public.admit_review_audience_team();
